var t=`0708-jagacida`;var n=`world-0708`;var a=`CV`;var o=`western-africa`;var r=4;var s=49;var d={en:`Jagacida`,ua:`Джаґасіда`};var l={en:`Jagacida is a Cabo Verde classic prepared with yellow onion, garlic, tomato, white rice. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Джаґасіда, страва кухні країни Кабо-Верде зі складниками: жовта цибуля, часник, помідор, білий рис. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var g=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,160,`g`],[`garlic`,3,`clove`],[`tomato`,290,`g`],[`sunflower-oil`,35,`ml`]]},{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 27 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 27 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:27,i:[[`white-rice`,320,`g`],[`canned-kidney-beans`,350,`g`],[`water`,570,`ml`]]},{en:`Take off the heat and let the rice rest under a clean towel or lid for about 7 minutes before serving.`,ua:`Зніміть із вогню та дайте рису відпочити під чистим рушником або кришкою приблизно 7 хвилин перед подаванням.`,t:[`rice-resting`,`fluffing-grains`],m:7,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,18,`g`]]}];var u={slug:t,id:n,country:`CV`,region:o,servings:4,minutes:49,title:d,text:l,steps:g};export{a as country,u as default,n as id,s as minutes,o as region,r as servings,t as slug,g as steps,l as text,d as title};